import { describe, expect, it } from 'vitest'
import { execFileSync } from 'node:child_process'
import { readFileSync } from 'node:fs'
import { resolve } from 'node:path'

// Resolve repo root relative to the frontend working directory used by vitest.
const repoRoot = resolve('..') // frontend/ is one level below repo root

describe('generatedGearSchema drift guard', () => {
  it('generatedGearSchema.ts is in sync with config/gear-schema.yaml', () => {
    // Call geargen --check via go run; it exits non-zero and prints a message
    // if either generated file differs from what the YAML would produce.
    try {
      execFileSync(
        'go',
        [
          'run',
          './cmd/geargen',
          '--repo-root',
          repoRoot,
          '--check',
        ],
        {
          cwd: resolve(repoRoot, 'services', 'api'),
          encoding: 'utf8',
          stdio: ['ignore', 'pipe', 'pipe'],
        },
      )
    } catch (err: unknown) {
      const msg = (err as { stderr?: string; stdout?: string }).stderr ?? (err as { message?: string }).message ?? String(err)
      throw new Error(
        `frontend/src/lib/generatedGearSchema.ts is out of sync with config/gear-schema.yaml.\n` +
          `Run ./scripts/generate-gear-schema.sh and commit the result.\n\n` +
          msg,
      )
    }
  })

  it('generatedGearSchema.ts starts with the canonical codegen header', () => {
    const content = readFileSync('src/lib/generatedGearSchema.ts', 'utf8')
    expect(content).toMatch(/^\/\/ Code generated by geargen; DO NOT EDIT\./)
  })
})
